import{_ as r,a as t}from"./chunks/ecosystem.BHQSxcYD.js";import{_ as a,o as s,c as i,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"source_hash":"133cbb42c8","source_commit":"2bdf116"},"headers":[],"relativePath":"fr/index.md","filePath":"fr/index.md"}'),o={name:"fr/index.md"};function l(u,e,d,p,c,m){return s(),i("div",null,[...e[0]||(e[0]=[n('<img src="'+r+'" style="zoom:70%;"><br><h2 id="what-is-xdrip" tabindex="-1">Qu&#39;est-ce que xDrip ? <a class="header-anchor" href="#what-is-xdrip" aria-label="Permalink to &quot;Qu&#39;est-ce que xDrip ? {#what-is-xdrip}&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>xDrip est une application Android non officielle et indépendante qui sert de centrale de données et de traitement entre de nombreux appareils différents.</p><p>Elle prend en charge les connexions sans fil avec les G6, One, One+, G7, Stelo, CareSens Air, Libre par NFC et Bluetooth, Aidex, Guardian, Simplera, les pompes Medtronic, le CGM Eversense, Libre 2 et 3, ainsi qu&#39;avec de nombreuses applications de fabricants de CGM ou de pompes (Pasta, iCan, CamAPS, Equil G, Vitatok, Glucotech, SiSensing, et d&#39;autres) grâce au lecteur de notifications de l&#39;application compagnon. Elle prend aussi en charge les lecteurs de glycémie Bluetooth comme le Contour Next One, l&#39;AccuChek Guide, le Verio Flex et le Diamond Mini, ainsi que des appareils comme le stylo à insuline Pendiq 2.0.</p><p>Les données de fréquence cardiaque et de podomètre sont récupérées depuis les montres Android Wear, Garmin, Fitbit et Pebble, et depuis les cadrans qui affichent les valeurs et courbes de glycémie.</p><p>L&#39;application offre des graphiques élaborés, de nombreuses options de personnalisation et de saisie de données, ainsi qu&#39;un modèle de simulation prédictive.</p><p>Une synchronisation instantanée dans les deux sens est possible en associant des téléphones abonnés. Les données peuvent aussi être envoyées vers un service web Nightscout ou téléchargées depuis celui-ci, ou envoyées directement vers Nocturne, Tidepool, MongoDB ou InfluxDB.</p><p>Vous pouvez personnaliser les alarmes, la lecture vocale des valeurs, les préférences d&#39;affichage, etc. Les utilisateurs du monde entier peuvent aussi améliorer les traductions directement depuis l&#39;application.</p><p>Vos données vous appartiennent et peuvent être exportées de nombreuses façons. xDrip communique aussi avec d&#39;autres applications, par exemple pour envoyer et recevoir des données en temps réel avec <a href="https://androidaps.readthedocs.io/fr/latest/index.html" target="_blank" rel="noreferrer">AndroidAPS</a>.</p><br><h2 id="ready-to-start-continue-here" tabindex="-1"><a href="./install/usethedoc.html">Prêt à commencer ? C&#39;est par ici !</a> <a class="header-anchor" href="#ready-to-start-continue-here" aria-label="Permalink to &quot;[Prêt à commencer ? C&#39;est par ici !](./install/usethedoc) {#ready-to-start-continue-here}&quot;">​</a></h2><br><h2 id="history" tabindex="-1">Historique <a class="header-anchor" href="#history" aria-label="Permalink to &quot;Historique {#history}&quot;">​</a></h2><p><a href="https://github.com/StephenBlackWasAlreadyTaken/DexDrip" target="_blank" rel="noreferrer">DexDrip</a> a été créé par Emma Black en 2014, puis est devenu <a href="http://stephenblackwasalreadytaken.github.io/xDrip/" target="_blank" rel="noreferrer">xDrip</a>, une application qui récupérait les données CGM d&#39;un récepteur G4 ou d&#39;un transmetteur et les envoyait vers <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>. Elle était accompagnée de l&#39;application de suivi <a href="http://stephenblackwasalreadytaken.github.io/NightWatch/" target="_blank" rel="noreferrer">Nightwatch</a> (obsolète).</p><p>Ce projet a ensuite été modifié par @jamorham pour devenir <a href="https://jamorham.github.io/#xdrip-plus" target="_blank" rel="noreferrer">xDrip</a>.</p><blockquote><p><em>Personal research version of xDrip</em></p></blockquote><img src="https://avatars.githubusercontent.com/u/12565568" style="zoom:33%;"><br><h2 id="disclaimer-and-warning" tabindex="-1"><strong>Avertissement</strong> <a class="header-anchor" href="#disclaimer-and-warning" aria-label="Permalink to &quot;**Avertissement** {#disclaimer-and-warning}&quot;">​</a></h2><ul><li><strong>Vous utilisez xDrip à vos propres risques : n&#39;utilisez pas les informations ou le code pour prendre des décisions médicales.</strong></li><li>Le <a href="https://github.com/NightscoutFoundation/xDrip" target="_blank" rel="noreferrer">code de github.com</a> est utilisé sans garantie ni support officiel d&#39;aucune sorte. Consultez la <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/LICENSE" target="_blank" rel="noreferrer">LICENCE</a> du dépôt pour plus de détails.</li><li>Tous les noms de produits et de sociétés, marques commerciales, marques de service et marques déposées sont la propriété de leurs détenteurs respectifs.</li></ul><p><strong>Remarque :</strong> ce projet n&#39;est associé à aucune des sociétés suivantes et n&#39;est approuvé par aucune d&#39;entre elles : Abbott Laboratories, Aidex, Ascenia, i-Sens, Companion Medical, Dexcom, Medtronic, Lifescan, Medtrum, Pendiq, Roche, Senseonics, Sibionics, GlucoRx.</p>',23)])])}const g=a(o,[["render",l]]);export{b as __pageData,g as default};
